// ❌ OLD: With createSignal, mutating a deep property forces copying
// every level of the object. Every consumer reading 'user()' re-evaluates,
// even if they only cared about user.id.
import { createSignal } from 'solid-js';

const [user, setUser] = createSignal({
  id: 1,
  profile: { name: 'Ada', age: 30 },
  settings: { theme: 'dark' }
});

function updateName(newName) {
  setUser(prev => ({
    ...prev,
    profile: {
      ...prev.profile,
      name: newName
    }
  })); // ❌ Allocates new object references for user and profile
}

import { createStore } from 'solid-js/store';

// ✅ NEW: createStore wraps objects in on-demand reactive proxies.
const [user, setUser] = createStore({
  id: 1,
  profile: { name: 'Ada', age: 30 },
  settings: { theme: 'dark' }
});

function updateName(newName) {
  // Surgical path update: only subscribers of user.profile.name re-run!
  // user.settings and user.id consumers are completely untouched.
  setUser('profile', 'name', newName);
}

